import svg from '../img/favicon.svg';

export const createRatingStars = rating => {
  const rounded = Math.round(Number(rating) || 0);
  let stars = '';
  for (let i = 0; i < 5; i++) {
    stars += i < rounded
      ? '<span class="filled-stars">★</span>'
      : '<span class="empty-star">★</span>';
  }
  return stars;
};